562	/* .card's border is a dark blue gradient in border-box. On paper that reads as
563	   a dirty outline, so light mode takes a plain rim and a real shadow instead —
564	   depth from the lift, not from the edge. */
565	/* :not(.card-on) — the selected-plan card (game/VPS deploy wizard) paints its
566	   own rainbow conic-gradient rim and dark fill regardless of theme, same idea
567	   as an nx-dark-island. This rule has higher specificity than `.card-on`
568	   alone (html + class + :not() beats one class), so without the exclusion it
569	   silently overwrote the selected treatment with the plain unselected card
570	   style — every plan card looked identical and nothing showed as picked. */
571	html[data-theme="light"] .card:not(.nx-dark-island .card):not(.card-on) {
572	  background: var(--color-surface);
573	  border: 1px solid var(--color-rim);
574	  box-shadow: 0 1px 2px rgb(15 23 42 / 0.05), 0 14px 32px -22px rgb(15 23 42 / 0.30);
575	}
576	html[data-theme="light"] .card-i:hover:not(.card-on) {
577	  background: #ffffff;
578	  border-color: color-mix(in srgb, var(--color-brand-500) 34%, transparent);
579	  box-shadow: 0 2px 4px rgb(15 23 42 / 0.06), 0 18px 38px -20px rgb(15 23 42 / 0.34);
580	}
581	/* .card-on itself is excluded above (it keeps its own rainbow rim in both
582	   themes), but its DARK #04214f fill — fine floating among other dark cards —
583	   reads as a jarring solid-navy hole punched into an otherwise all-white plan
584	   grid in light mode ("the highlight card is not look good"). Keep the same
585	   travelling conic-gradient rim (the part that actually reads as "selected")
586	   and swap only the fill and glow for a light surface. */
587	html[data-theme="light"] .card-on {
588	  background:
589	    linear-gradient(#fff, #fff) padding-box,
590	    conic-gradient(from var(--orbit),
