594	  box-shadow: inset 0 0 16px -8px rgba(20,197,228,0.16),
595	              0 0 20px -10px rgba(20,197,228,0.35),
596	              0 0 26px -12px rgba(214,35,225,0.28),
597	              0 10px 26px rgba(15,23,42,0.14);
598	}
