{/* Narrow tiles so a full family row fits without wrapping.
    Bounded height + its own scroll, NOT left to the deck's JS-measured
    slide height: `Deck` (below) sizes `.deck` — a hard `overflow-hidden`
    — off a `ResizeObserver` on the whole slide, and this Fold can also
    grow (Server settings + Add-ons open together, see <Fold>). Any gap
    between the two — the observer's callback runs a frame behind the
    CSS grid-rows reveal, or the real catalogue simply carries more OS
    families than this sandbox's four (Windows/CentOS/Fedora/Arch all
    have icons and a pretty name already, see familyLabel) — was rows of
    this grid getting sliced off by that outer `overflow-hidden` with no
    scrollbar and no way back, not a wrap failure: `auto-fill` cannot
    overflow its own row. Capping height here and scrolling INSIDE the
    grid means every option stays reachable regardless of how the deck
    around it is sized. */}
<div className="grid max-h-[300px] gap-2 overflow-y-auto pr-1 [grid-template-columns:repeat(auto-fill,minmax(96px,1fr))]">
  {families.map(([fam, items]) => {
    const on = items.some((x) => x.id === o.osId);
    const head = items[0];
    return (
      <Pick key={fam} on={on}
            onClick={() => set("osId", items[0].id)}
            className="flex flex-col items-center gap-1.5 px-1.5 py-2.5 text-center">
        {/* the third-party mark where one exists, the interface glyph
            otherwise — a cPanel drawn as a generic cube is not an icon */}
        {head.spriteKey
          ? <AppIcon name={head.spriteKey} size={26} />
